    @staticmethod
    def get(icon: str, size: int, color: Color):
        key = f"{icon}_{size}_{color.hex}"
        
        if Icons._cache.get(key, None) is None:
            svg_string = _SVGS[icon]
            
            size = vec2(size)
            width, height = round(size.x), round(size.y)
            
            color = color.hex
            
            if not color.startswith("#"):
                color = f"#{color}"
            
            custom_svg = svg_string.strip().replace('fill="currentColor"', f'fill="{color}"')
            
            png_bytes = bytes(svg_to_bytes(svg_string=custom_svg, width=width, height=height))
            
            surface = pg.image.load(io.BytesIO(png_bytes)).convert_alpha()
            Icons._cache[key] = surface
        else:
            surface = Icons._cache.get(key)
        
        if surface is None:
            raise "Error getting icon"
        
        return Texture.from_surface(surface)


